/* @autogenerated */
package net.civeira.phylax.feature.observe.ingest;

import java.util.Set;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.config.ObserveSettings;

class TelemetryMapperScrubUnitTest {

  private static final Set<String> GLOBAL =
      ObserveSettings.keys("password,secret,token,authorization,cookie,set-cookie,api-key");

  @Test
  @DisplayName("The key or one of its dotted segments masks the attribute, in any case and with _ as -")
  void masked() {
    Assertions.assertTrue(TelemetryMapper.masked("password", GLOBAL, Set.of()));
    Assertions
        .assertTrue(TelemetryMapper.masked("http.request.header.Authorization", GLOBAL, Set.of()));
    Assertions
        .assertTrue(TelemetryMapper.masked("http.response.header.set-cookie", GLOBAL, Set.of()));
    Assertions.assertTrue(TelemetryMapper.masked("API_KEY", GLOBAL, Set.of()));
    Assertions
        .assertTrue(TelemetryMapper.masked("customer.iban", GLOBAL, ObserveSettings.keys("iban")));
  }

  @Test
  @DisplayName("A key that only contains a scrub field as text is kept")
  void kept() {
    Assertions.assertFalse(TelemetryMapper.masked("http.route", GLOBAL, Set.of()));
    Assertions.assertFalse(TelemetryMapper.masked("tokenizer.name", GLOBAL, Set.of()));
    Assertions.assertFalse(TelemetryMapper.masked("customer.iban", GLOBAL, Set.of()));
  }
}
